{
  "findings": [
    {
      "check_id": "CKV_AWS_19",
      "title": "Ensure all data stored in the S3 bucket is securely encrypted at rest",
      "resource": "aws_s3_bucket.bucket_2",
      "severity": "HIGH",
      "explanation": "The S3 bucket has server-side encryption configured, but it is not enforced for all objects."
    },
    {
      "check_id": "CKV_AWS_20",
      "title": "Ensure the S3 bucket does not allow unencrypted object uploads",
      "resource": "aws_s3_bucket.bucket_2",
      "severity": "HIGH",
      "explanation": "The S3 bucket does not have a policy to deny unencrypted object uploads."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "bucket_2" {
  bucket = "roger-bucket-2"
  acl    = var.bucket_acl
  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        kms_master_key_id = aws_kms_key.my_key.arn
        sse_algorithm     = "aws:kms"
      }
    }
  }
}
resource "aws_s3_bucket_policy" "bucket_2_policy" {
  bucket = aws_s3_bucket.bucket_2.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyIncorrectEncryptionHeader"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:PutObject"
        Resource = "${aws_s3_bucket.bucket_2.arn}/*"
        Condition = {
          StringNotEquals = {
            "s3:x-amz-server-side-encryption" = "aws:kms"
          }
          Null = {
            "s3:x-amz-server-side-encryption" = true
          }
        }
      },
      {
        Sid       = "DenyUnencryptedObjectUploads"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:PutObject"
        Resource = "${aws_s3_bucket.bucket_2.arn}/*"
        Condition = {
          Null = {
            "s3:x-amz-server-side-encryption" = true
          }
        }
      }
    ]
  })
}",
  "fix_summary": "Added an S3 bucket policy to enforce encryption for all objects and deny unencrypted object uploads."
}
